// Parse la réponse JSON générée par Claude
let rawText = $input.first().json.content[0].text.trim();
rawText = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
const post = JSON.parse(rawText);

return [{
  json: {
    produit: $('Sélection du produit du jour').first().json.nom,
    accroche: post.accroche,
    corps: post.corps,
    cta: post.cta,
    hashtags: post.hashtags.join(' '),
    promptImage: post.promptImage,
    dateGeneration: new Date().toISOString()
  }
}];
